UPDATE div_trip_inspection_template_items SET section_name='Lighting / लाईटिंग', item_no='iv', label_en='Check the working of head light with DC-DC converter positions', label_hi='डीसी-डीसी कन्वर्टर की विभिन्न स्थितियों के साथ हेड लाइट के कार्य की जाँच करें। अ) मोड-1 ब) मोड-2', standard_value='Both position working normal', is_required=1 WHERE template_id=346 AND sort_order=29; -- source_row 36
UPDATE div_trip_inspection_template_items SET section_name='Pantograph & Roof Equipments', item_no='i', label_en='inspect the entire upper structure of the pantograph assembly and check that the assembly horn, wear strip and support assembly have no cracks.', label_hi='पैन्‍टोग्राफ असेंबली के पूरे ऊपरी ढॉचे की विजुअल जॉच करें तथा जॉच करें कि असेम्‍बली हॉर्न, विअर स्‍ट्रीप तथा सपोर्ट असेम्‍बली में कोई क्रेक नहीं।', standard_value='No Crack', is_required=1 WHERE template_id=346 AND sort_order=35; -- source_row 44
UPDATE div_trip_inspection_template_items SET section_name='Pantograph & Roof Equipments', item_no='vi', label_en='check for any cracks.', label_hi='फुट माऊंटिग इंसुलेटर को साफ करें और चेक करे कि कोई क्रेक तो नहीं है।', standard_value='Clean/No crack', is_required=1 WHERE template_id=346 AND sort_order=40; -- source_row 49
UPDATE div_trip_inspection_template_items SET section_name='Pantograph & Roof Equipments', item_no='viii', label_en='Check upper thrust of both the pantograph. IR03- On 7.0Kgf, Panto pan should not leave OHE while on 7.5Kgf, panto pan should leave OHE by a paper gap between OHE & Panto pan. HRPT- After putting 7.0Kgf, pull the panto pan towards lower side, it must be stop wherever pulling force removed. Similarly, during application of upper force, Panto pan should stop wherever upper force removed.', label_hi='दोनों पेंटोग्राफ के ऊपरी थ्रस्ट की जाँच करें। दोनों पैंटोग्राफ की अपर थ्रस्ट की जांच करें। IR03 - 7.0 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन को ओएचई (OHE) से अलग नहीं होना चाहिए, जबकि 7.5 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन और ओएचई के बीच कागज़ की मोटाई जितना अंतर आ जाना चाहिए। HRPT - 7.0 किलोग्राम-फोर्स (Kgf) लगाने के बाद पैंटो पैन को नीचे की ओर खींचें, खींचने की ताकत हटते ही पैंटो पैन को वहीं रुक जाना चाहिए। इसी प्रकार, जब ऊपर की ओर बल लगाया जाए, तो बल हटते ही पैंटो पैन को वहीं रुक जाना चाहिए।', standard_value='7.0 किलोग्राम / 7.0 kgf', is_required=1 WHERE template_id=346 AND sort_order=42; -- source_row 51
UPDATE div_trip_inspection_template_items SET section_name='Pantograph & Roof Equipments', item_no='ix', label_en='Ensure PRV setting of HRPT Pantograph is within limit. Ref:- RDSO letter no. No. EL/2.2.1/High Reach/Faiveley)', label_hi='सुनिश्चित करें कि एचआरपीटी पैंटोग्राफ की पीआरवी सेटिंग सीमा के भीतर है।', standard_value='Within prescribed PRV setting limit', is_required=1 WHERE template_id=346 AND sort_order=43; -- source_row 52
UPDATE div_trip_inspection_template_items SET section_name='Pantograph & Roof Equipments', item_no='xiv', label_en='Check ET 1 & 2 for proper gap and clean it with polish paper.', label_hi='ई टी-1 व ई टी-2 के गेप नापे व पाॅलीश पेपर से साफ करें ।', standard_value='ET-1: 210 ± 5.0 mm; ET-2: 85 to 90 mm', is_required=1 WHERE template_id=346 AND sort_order=48; -- source_row 57
