UPDATE div_trip_inspection_template_items SET section_name='Mechanical / यांत्रिक', item_no='i', label_en='Check condition of brake block and change if required. Adjust the piston stroke Check the gap between brake block & wheel in brake release condition 10mm & for WAG7 it should be 6mm).', label_hi='ब्रे्रेक ब्लाक को चेक करें, यदि आवश्यकता हो तब बदली करे। पिस्टन स्ट्रोक का समायोजन करें। लोको ब्रेक रिलीज स्थिति में पहिये से ब्रेक ब्लॉक के बीच का अंतराल 10 मिमी और WAG7 के लिए 6 मिमी होना चाहिए।', standard_value='Condemned brake block changed and brake piston stroke adjusted.', is_required=1 WHERE template_id=346 AND sort_order=95; -- source_row 117
