UPDATE div_trip_inspection_template_items SET section_name='Mechanical / यांत्रिक', item_no='xvi', label_en='Check intactness of connection strap bolts at all wheels Check Trunion position at all wheels Ensure clearance between connections to guide strip in WAP-1 & WAP-4 locos. Ensure no rubbing of connection strap with wheel of WAP-1 & WAP-4 locos at all wheels Check vertical & lateral play of hangers Check intactness of brake hanger top pin, split pin & safety sling. Check Trunion locking with split pin & proper oiling in WAP-1 & WAP-4 locos. Ensure safety sling for connection strap in WAP-1 & WAP-4 locos.', label_hi='डब्लुएपी 1, डब्लुएपी 4 की ब्रेक रिगिंग: सभी व्हील के कनेक्शन स्ट्रैप बोल्ट, ट्रुनियन स्थिति, गाइड स्ट्रिप क्लियरेंस, कनेक्शन स्ट्रैप रबिंग, हैंगर प्ले, ब्रेक हैंगर टॉप पिन, स्प्लिट पिन, सेफ्टी स्लिंग, ट्रुनियन लॉकिंग और ऑयलिंग की जाँच करें।', standard_value='Intact Intact Intact Intact Intact Intact Intact Intact', is_required=1 WHERE template_id=346 AND sort_order=110; -- source_row 132
UPDATE div_trip_inspection_template_items SET section_name='Fp Angle Cock And Hose Pipe', item_no='111', label_en='Check BP/FP angle cock operation, BP/FP flexible hoses and air leakage in both cabs.', label_hi='दोनो कैब में लगे बीपी तथा एफपी एंगल कॉक की ओपन तथा क्लोज पोजीशन में कार्य-जाँच करें। बीपी तथा एफपी फ्लेक्सीबल होस तथा एंगल कॉक में एयर लीकेज की जाँच करें। बीपी/एफपी होज़ पाइप में कोई डैमेज न हो, यह सुनिश्चित करें।', standard_value='Operation Normal', is_required=1 WHERE template_id=346 AND sort_order=111; -- source_row 134
